+// SelectableFields returns the selectable fields declared for key. Returns nil
+// if r is nil or key has no selectable fields.
+func (r *SearchFieldsRegistry) SelectableFields(key LowerGroupResource) []string {
+	if r == nil {
+		return nil
+	}
+	r.mu.RLock()
+	defer r.mu.RUnlock()
+	return r.selectableFields[key]
+}
+
+// IsSelectable reports whether field is declared as a selectable field for key.
+func (r *SearchFieldsRegistry) IsSelectable(key LowerGroupResource, field string) bool {
+	if r == nil {
+		return false
+	}
+	r.mu.RLock()
+	defer r.mu.RUnlock()
+	return slices.Contains(r.selectableFields[key], field)
+}
