+// DeleteAuthInfo implements login.Store.
+func (s *Store) DeleteAuthInfo(ctx context.Context, cmd *login.DeleteAuthInfoCommand) error {
+	ctx, span := s.tracer.Start(ctx, "authinfo.k8s.DeleteAuthInfo")
+	defer span.End()
+
+	if cmd == nil {
+		return nil
+	}
+
+	authClient, userClient, namespace, err := s.clients(ctx)
+	if err != nil {
+		return err
+	}
+
+	userUID := cmd.UserUID
+	if userUID == "" {
+		if cmd.UserAuth != nil && cmd.UserAuth.UserUID != "" {
+			userUID = cmd.UserAuth.UserUID
+		} else {
+			userID := cmd.UserId
+			if userID == 0 && cmd.UserAuth != nil {
+				userID = cmd.UserAuth.UserId
+			}
+			userUID, err = s.userUID(ctx, userClient, namespace, userID)
+			if err != nil {
+				if errors.Is(err, user.ErrUserNotFound) {
+					return nil
+				}
+				return err
+			}
+		}
+	}
+
+	authModule := cmd.AuthModule
+	if authModule == "" && cmd.UserAuth != nil {
+		authModule = cmd.UserAuth.AuthModule
+	}
+	if authModule == "" {
+		return errors.New("authinfok8s: DeleteAuthInfo requires an AuthModule")
+	}
+
+	name := iamv0alpha1.EncodeName(userUID, authModule)
+	if err := authClient.Delete(ctx, resource.Identifier{Namespace: namespace, Name: name}, resource.DeleteOptions{}); err != nil && !apierrors.IsNotFound(err) {
+		return err
+	}
+	return nil
+}
