+func TestStore_DeleteAuthInfo(t *testing.T) {
+	type testCase struct {
+		name    string
+		cmd     *login.DeleteAuthInfoCommand
+		handler http.HandlerFunc
+		wantErr bool
+		check   func(t *testing.T)
+	}
+
+	cases := []testCase{
+		func() testCase {
+			var deleted []string
+			return testCase{
+				name: "deletes specific module for user",
+				cmd: &login.DeleteAuthInfoCommand{
+					UserId:     42,
+					AuthModule: login.LDAPAuthModule,
+				},
+				handler: func(w http.ResponseWriter, r *http.Request) {
+					switch {
+					case strings.Contains(r.URL.Path, "/users"):
+						usersResponse(t, w, "user-uid")
+					case r.Method == http.MethodDelete:
+						deleted = append(deleted, r.URL.Path)
+						w.WriteHeader(http.StatusOK)
+					default:
+						t.Fatalf("unexpected request: %s %s", r.Method, r.URL.Path)
+					}
+				},
+				check: func(t *testing.T) {
+					assert.Equal(t, []string{
+						"/apis/iam.grafana.app/v0alpha1/namespaces/org-7/authinfos/user-uid.ldap",
+					}, deleted)
+				},
+			}
+		}(),
+		{
+			name: "user not found is a no-op",
+			cmd: &login.DeleteAuthInfoCommand{
+				UserId:     42,
+				AuthModule: login.LDAPAuthModule,
+			},
+			handler: func(w http.ResponseWriter, r *http.Request) {
+				if strings.Contains(r.URL.Path, "/users") {
+					noUsersResponse(t, w)
+					return
+				}
+				t.Fatalf("unexpected request: %s %s", r.Method, r.URL.Path)
+			},
+		},
+		{
+			name: "missing auth module returns error",
+			cmd: &login.DeleteAuthInfoCommand{
+				UserId: 42,
+			},
+			wantErr: true,
+		},
+	}
+
+	for _, tc := range cases {
+		t.Run(tc.name, func(t *testing.T) {
+			store := newTestStore(t, tc.handler)
+			err := store.DeleteAuthInfo(contextWithReqContext(7), tc.cmd)
+			if tc.wantErr {
+				require.Error(t, err)
+				return
+			}
+			require.NoError(t, err)
+			if tc.check != nil {
+				tc.check(t)
+			}
+		})
+	}
+}
